play.onclick=()=>{if(video.paused)video.play().catch(()=>{});else video.pause()};mute.onclick=()=>{video.muted=!video.muted;updateVideo()};['timeupdate','durationchange','loadedmetadata','play','pause','volumechange'].forEach(name=>video.addEventListener(name,updateVideo));
let scrubPointer=null;
