window.addEventListener('pointerup',endScrub);window.addEventListener('pointercancel',endScrub);seek.addEventListener('lostpointercapture',endScrub);seek.addEventListener('input',()=>{if(!scrubbing&&Number.isFinite(video.duration))applyScrubRatio(Number(seek.value)/1000)});
function withinVideo(e){const r=video.getBoundingClientRect(),w=video.videoWidth,h=video.videoHeight;if(!w||!h)return false;const scale=Math.min(r.width/w,r.height/h),rw=w*scale,rh=h*scale;return e.clientX>=r.left+(r.width-rw)/2&&e.clientX<=r.left+(r.width+rw)/2&&e.clientY>=r.top+(r.height-rh)/2&&e.clientY<=r.top+(r.height+rh)/2}
function isStandalone(){return navigator.standalone===true||matchMedia('(display-mode: standalone)').matches}
function enterCinema(){viewer.classList.add('cinema');syncSystemBackdrop();if(!isStandalone()&&document.fullscreenEnabled&&viewer.requestFullscreen)viewer.requestFullscreen().catch(()=>{})}
function exitCinema(){viewer.classList.remove('cinema');syncSystemBackdrop();if(document.fullscreenElement&&document.exitFullscreen)document.exitFullscreen().catch(()=>{})}
viewer.addEventListener('click',e=>{if(!viewer.classList.contains('cinema'))return;e.stopPropagation();if(Date.now()-gestureMovedAt<400)return;exitCinema()},true);video.addEventListener('click',e=>{if(Date.now()-gestureMovedAt<400||!withinVideo(e))return;enterCinema();e.stopPropagation()});wrap.addEventListener('click',e=>{if(e.target===video||e.target.closest('.video-controls')||Date.now()-gestureMovedAt<400)return;enterCinema()});document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&viewer.classList.contains('cinema')&&document.fullscreenEnabled)exitCinema()});updateVideo();

function syncSystemBackdrop(){const cinema=viewer.classList.contains('cinema'),theme=globalThis.PHOTO_THEME||'system';document.documentElement.dataset.theme=cinema||theme==='dark'||theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';document.documentElement.classList.toggle('cinema-active',cinema)}
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',syncSystemBackdrop);window.addEventListener('pageshow',syncSystemBackdrop);document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncSystemBackdrop()});syncSystemBackdrop();

// Library filter popover: unavailable metadata-dependent options remain disabled in the prototype.
function positionFilterMenu(){const menu=$('#filterMenu'),rect=$('#filter').getBoundingClientRect(),top=Math.max(12,rect.top),left=12;menu.style.top=`${top}px`;menu.style.left=`${left}px`;menu.style.right='auto';menu.style.maxHeight=`${Math.max(150,innerHeight-top-12)}px`;menu.style.transformOrigin=`${rect.left+rect.width/2-left}px ${rect.top+rect.height/2-top}px`}
