function showFilterPage(id){['filterMain','filterMedia','filterView'].forEach(name=>$('#'+name).classList.toggle('hidden',name!==id));$('#filterMenu').scrollTop=0}
function updateFilterChecks(){document.querySelectorAll('[data-library-filter]').forEach(b=>b.querySelector('.filter-check').textContent=b.dataset.libraryFilter===libraryFilter?'✓':'');document.querySelectorAll('[data-media-filter]').forEach(b=>b.querySelector('.filter-check').textContent=b.dataset.mediaFilter===mediaFilter?'✓':'')}
$('#filter').setAttribute('aria-haspopup','dialog');$('#filter').setAttribute('aria-expanded','false');$('#filterMediaOpen').onclick=()=>showFilterPage('filterMedia');$('#filterViewOpen').onclick=()=>showFilterPage('filterView');document.querySelectorAll('[data-filter-back]').forEach(b=>b.onclick=()=>showFilterPage('filterMain'));
document.querySelectorAll('[data-library-filter]').forEach(b=>b.onclick=()=>{libraryFilter=b.dataset.libraryFilter;updateFilterChecks();refreshLibrary();setFilterMenu(false)});document.querySelectorAll('[data-media-filter]').forEach(b=>b.onclick=()=>{mediaFilter=b.dataset.mediaFilter;updateFilterChecks();refreshLibrary();setFilterMenu(false)});document.querySelectorAll('[data-view-size]').forEach(b=>b.onclick=()=>{setSize(b.dataset.viewSize);setFilterMenu(false)});
document.addEventListener('pointerdown',e=>{if(filterMenuOpen&&!e.target.closest('#filterMenu')&&!e.target.closest('#filter'))setFilterMenu(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape')setFilterMenu(false)});window.addEventListener('resize',()=>{if(filterMenuOpen)positionFilterMenu()});updateFilterChecks();

// Drag the thumbnail strip to move through the current sequence without lifting.
const strip=$('#filmstrip');let stripDrag=null;
