strip.addEventListener('touchstart',e=>{if(e.touches.length!==1)return;finishSlideTransition();if(busy)return;const button=e.target.closest('button'),index=button?Number(button.dataset.index):current;stripDrag={startX:e.touches[0].clientX,startY:e.touches[0].clientY,startPos:Math.max(0,viewerSequence.indexOf(index)),moved:false}},{passive:true});
