// The compact browsing controls stay visible until the end of the library.
let previousLibraryY=window.scrollY,lastControlsFrame=0,browsingControls=false,browseResumeOnScroll=false;
function setBrowsingControls(on){const desktop=matchMedia('(min-width: 1000px) and (pointer: fine)').matches;if(desktop)on=false;browsingControls=on;const nav=document.querySelector('.bottom'),collection=$('#collectionTab'),scale=$('#scale');nav.classList.toggle('browsing',on);const add=$('#libraryUploadButton');if(add){add.disabled=on;add.tabIndex=on?-1:0;add.setAttribute('aria-hidden',String(on));}collection.disabled=on;collection.tabIndex=on?-1:0;collection.setAttribute('aria-hidden',String(on));scale.setAttribute('aria-hidden',String(!on&&!desktop));scale.inert=!on&&!desktop;if(!on)previousLibraryY=window.scrollY;if(typeof syncScale==='function'&&on)requestAnimationFrame(syncScale)}
